//! Golden tests for pgfuncs::uuid against PostgreSQL 17 output
//! (generated by tests/gen/gen_uuid.py).

use pgfuncs::uuid;
use proptest::prelude::*;
use serde_json::Value;

fn load(name: &str) -> Vec<Value> {
    let path = format!("{}/tests/data/{}", env!("CARGO_MANIFEST_DIR"), name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("reading {path}: {e}"));
    text.lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| serde_json::from_str(l).unwrap_or_else(|e| panic!("bad json line {l}: {e}")))
        .collect()
}

#[test]
fn uuid_golden() {
    let mut failures = Vec::new();
    let recs = load("uuid_golden.jsonl");
    let mut ok_cases = 0;
    for rec in &recs {
        assert_eq!(rec["fn"], "uuid_in");
        let input = rec["args"][0].as_str().unwrap();
        let got = uuid::parse(input);
        match (rec.get("error"), got) {
            (Some(want), Err(e)) => {
                let sqlstate = want["sqlstate"].as_str().unwrap();
                let message = want["message"].as_str().unwrap();
                if e.sqlstate != sqlstate || e.message != message || e.detail.as_deref() != want["detail"].as_str() {
                    failures.push(format!("{input:?}: error got {e:?} want {want}"));
                }
            }
            (Some(want), Ok(v)) => failures.push(format!("{input:?}: expected error {want}, got {v:?}")),
            (None, Err(e)) => failures.push(format!("{input:?}: unexpected error {e:?}")),
            (None, Ok(v)) => {
                ok_cases += 1;
                let out = uuid::format(&v);
                let want = rec["result"].as_str().unwrap();
                if out != want {
                    failures.push(format!("{input:?}: got {out:?} want {want:?}"));
                }
                if uuid::parse(&out) != Ok(v) {
                    failures.push(format!("{input:?}: output {out:?} does not reparse"));
                }
            }
        }
    }
    assert!(recs.len() > 1000 && ok_cases > 100, "too few golden cases");
    if !failures.is_empty() {
        panic!("{} of {} golden cases failed:\n{}", failures.len(), recs.len(), failures.join("\n"));
    }
}

proptest! {
    #[test]
    fn format_parse_roundtrip(bytes in prop::array::uniform16(any::<u8>())) {
        let s = uuid::format(&bytes);
        prop_assert_eq!(s.len(), 36);
        prop_assert_eq!(uuid::parse(&s), Ok(bytes));
        prop_assert_eq!(uuid::parse(&s.to_uppercase()), Ok(bytes));
        prop_assert_eq!(uuid::parse(&format!("{{{}}}", s.replace('-', ""))), Ok(bytes));
    }
}
